-- Lumi — traduções para inglês do conteúdo do banco (Bloco D).
-- Gerado a partir de revisão em português; rodar depois da migration 00029. Seguro repetir (on conflict).
-- Textos: devocionais (content), planos (reading_plans) e desafios do catálogo (challenges).

on conflict (content_id, language) do update set title = excluded.title, body = excluded.body, application_text = excluded.application_text, challenge_text = excluded.challenge_text, prayer_text = excluded.prayer_text;

on conflict (plan_id, language) do update set title = excluded.title, description = excluded.description;

on conflict (challenge_id, language) do update set title = excluded.title, description = excluded.description;
